class Solution {
    public int largestSubmatrix(int[][] matrix){
        int cols=matrix[0].length,answer=0;
        int[] heights=new int[cols];
        for(int[] row:matrix){
            for(int col=0;col<cols;col++)heights[col]=row[col]==0?0:heights[col]+1;
            int[] sorted=heights.clone();
            Arrays.sort(sorted);
            for(int index=0;index<cols;index++)answer=Math.max(answer,sorted[index]*(cols-index));
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun largestSubmatrix(matrix:Array<IntArray>):Int{
        val heights=IntArray(matrix[0].size);
        var answer=0;
        for(row in matrix){
            for(col in row.indices)heights[col]=if(row[col]==0)0 else heights[col]+1;
            val sorted=heights.sortedDescending();
            for(index in sorted.indices)answer=maxOf(answer,sorted[index]*(index+1))
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int largestSubmatrix(vector<vector<int>>& matrix){
        int cols=matrix[0].size(),answer=0;
        vector<int> heights(cols);
        for(auto& row:matrix){
            for(int col=0;col<cols;++col)heights[col]=row[col]?heights[col]+1:0;
            auto sorted=heights;
            sort(sorted.rbegin(),sorted.rend());
            for(int index=0;index<cols;++index)answer=max(answer,sorted[index]*(index+1));
        }
        return answer;
    }
};
